import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    lines = raw_csv.splitlines(keepends=True)
    start = 0
    while start < len(lines):
        stripped = lines[start].lstrip()
        if not stripped.strip() or stripped.startswith("#"):
            start += 1
        else:
            break

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        records = list(csv.reader(io.StringIO("".join(lines[start:]), newline="")))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    existing = set(columns)
    index = 1
    while len(columns) < width:
        name = "extra_" + str(index)
        index += 1
        if name not in existing:
            columns.append(name)
            existing.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
